questions.code:
export function add(a, b) {
  return a + b;
}

export default function load() {
  return true;
}

export function add(a, b) {
  return a + b;
}

questions.solution:
function namedExport() {
  return "export function add(a, b) {\n  return a + b;\n}";
}

tests.expected:
export function add(a, b) {
  return a + b;
}

questions.solution:
function defaultExport() {
  return "export default function load() {\n  return true;\n}";
}

tests.expected:
export default function load() {
  return true;
}
